using System.Text;
using OcctSharp.Generator.Model;
using OcctSharp.Generator.Transformation;

namespace OcctSharp.Generator.Emission;

internal static class CopiedCollectionSupportEmitter
{
    internal static string Template(string name)
    {
        using Stream stream = typeof(CopiedCollectionSupportEmitter).Assembly.GetManifestResourceStream(
            "OcctSharp.Generator.Emission." + name) ?? throw new InvalidDataException("Missing copied collection template " + name);
        using StreamReader reader = new(stream);
        return reader.ReadToEnd().Replace("\r\n", "\n", StringComparison.Ordinal);
    }

    internal static IReadOnlyList<GeneratedFile> Emit()
    {
        const string stem = "OcctSharp.Foundation.CopiedCollections.Generated";
        StringBuilder h = new("// <auto-generated />\n#pragma once\n#include \"../../include/OcctSharp.Native.h\"\n#include \"../Geometry/OcctSharp.Geometry.Values.Generated.h\"\n#ifdef __cplusplus\nextern \"C\" {\n#endif\n");
        StringBuilder cpp = new("// <auto-generated />\n#include \"" + stem + ".h\"\n#include <Standard_Failure.hxx>\nvoid OcctSharp_Internal_SetLastError(const char*);\n#include \"OcctSharp.Foundation.CopiedSupport.Generated.hxx\"\nusing namespace OcctSharpCollections;\n");
        StringBuilder cs = new(Template("copied-collections-managed.txt"));
        cs.AppendLine("internal sealed class CopiedHandle : SafeHandleZeroOrMinusOneIsInvalid {\n  private readonly int _kind;\n  internal CopiedHandle(nint token, int kind) : base(true) { _kind = kind; SetHandle(token); }\n  protected override bool ReleaseHandle() { CopiedInterop.Release(handle, _kind); return true; }\n}");
        cs.AppendLine("internal static unsafe partial class CopiedInterop {\n  static CopiedInterop() => NativeLibraryResolver.EnsureRegistered(typeof(CopiedInterop).Assembly);\n  internal static void Release(nint token, int kind) { switch (kind) {");
        int kind = 0;
        foreach (var c in CopiedCollectionOperationContract.Collections)
            cs.AppendLine("    case " + kind++ + ": Release" + c.Name + "(token); break;");
        cs.AppendLine("    default: throw new InvalidOperationException(\"Unknown copied collection kind.\");\n  } }");
        kind = 0;
        foreach (var c in CopiedCollectionOperationContract.Collections)
        {
            string prefix = "occtsharp_copy_" + c.Name.ToLowerInvariant();
            string lower = c.Sequence ? "1" : "value->Lower()";
            string count = "value->Length()";
            string ctor = c.Sequence ? "std::make_shared<" + c.NativeType + ">()" : "std::make_shared<" + c.NativeType + ">(lower, lower + (count - 1))";
            // Conversion expressions refer to an element, not the shared_ptr container.
            string assign = c.Sequence ? "value->Append(" + c.ToNative.Replace("value", "element", StringComparison.Ordinal) + ");"
                : "value->SetValue(lower + i, " + c.ToNative.Replace("value", "element", StringComparison.Ordinal) + ");";
            string createSig = "OcctSharp_Status OCCTSHARP_CALL " + prefix + "_create(const " + c.Abi + "* data, int32_t lower, int32_t count, void** result)";
            string infoSig = "OcctSharp_Status OCCTSHARP_CALL " + prefix + "_info(const void* token, int32_t* lower, int32_t* count)";
            string copySig = "OcctSharp_Status OCCTSHARP_CALL " + prefix + "_copy(const void* token, " + c.Abi + "* data, int32_t capacity)";
            string releaseSig = "void OCCTSHARP_CALL " + prefix + "_release(void* token)";
            foreach (string signature in new[] { createSig, infoSig, copySig, releaseSig }) h.AppendLine("OCCTSHARP_API " + signature + ";");
            cpp.AppendLine(createSig + " {\n  if (!result) return OCCTSHARP_STATUS_INVALID_ARGUMENT;\n  *result = nullptr;\n  return Guard([&] {\n    Bounds(lower, count, " + (c.Sequence ? "true" : "false") + ");\n    Require(count == 0 || data, \"Null collection input buffer.\");\n    auto value = " + ctor + ";\n    for (int i = 0; i < count; ++i) { const auto element = data[i]; " + assign + " }\n    *result = OcctSharpOwned::Register(std::move(value), typeid(" + c.NativeType + "));\n  });\n}");
            cpp.AppendLine(infoSig + " {\n  if (!lower || !count) return OCCTSHARP_STATUS_INVALID_ARGUMENT;\n  *lower = 0; *count = 0;\n  return Guard([&] { auto value = OcctSharpOwned::Lease<const " + c.NativeType + ">(token); *lower = " + lower + "; *count = " + count + "; });\n}");
            cpp.AppendLine(copySig + " {\n  return Guard([&] {\n    auto value = OcctSharpOwned::Lease<const " + c.NativeType + ">(token);\n    Require(capacity >= " + count + ", \"Collection output capacity is too small.\");\n    Require(" + count + " == 0 || data, \"Null collection output buffer.\");\n    std::vector<" + c.Abi + "> copied; copied.reserve(" + count + ");\n    for (int i = 0; i < " + count + "; ++i) { const auto& element = value->Value(" + lower + " + i); copied.push_back(" + c.FromNative.Replace("value", "element", StringComparison.Ordinal) + "); }\n    if (!copied.empty()) std::copy(copied.begin(), copied.end(), data);\n  });\n}");
            cpp.AppendLine(releaseSig + " { OcctSharpOwned::Release(token, typeid(" + c.NativeType + ")); }");
            string managedLower = c.Sequence ? "1" : "value.Lower";
            cs.AppendLine("  [LibraryImport(\"OcctSharp.Native\", EntryPoint = \"" + prefix + "_create\")]\n  private static partial NativeStatus Create" + c.Name + "(" + c.Managed + "* data, int lower, int count, out nint result);");
            cs.AppendLine("  [LibraryImport(\"OcctSharp.Native\", EntryPoint = \"" + prefix + "_info\")]\n  private static partial NativeStatus Info" + c.Name + "(nint token, out int lower, out int count);");
            cs.AppendLine("  [LibraryImport(\"OcctSharp.Native\", EntryPoint = \"" + prefix + "_copy\")]\n  private static partial NativeStatus Copy" + c.Name + "(nint token, " + c.Managed + "* data, int capacity);");
            cs.AppendLine("  [LibraryImport(\"OcctSharp.Native\", EntryPoint = \"" + prefix + "_release\")]\n  private static partial void Release" + c.Name + "(nint token);");
            cs.AppendLine("  internal static CopiedHandle Create" + c.Name + "(" + c.Friendly + " value) {\n    ArgumentNullException.ThrowIfNull(value);\n    fixed (" + c.Managed + "* data = value.Values) {\n      NativeError.ThrowIfFailed(Create" + c.Name + "(data, " + managedLower + ", value.Count, out var result), \"" + prefix + "_create\");\n      try { return new CopiedHandle(result, " + kind + "); } catch { Release" + c.Name + "(result); throw; }\n    }\n  }");
            cs.AppendLine("  internal static " + c.Friendly + " Read" + c.Name + "(nint token) {\n    NativeError.ThrowIfFailed(Info" + c.Name + "(token, out var lower, out var count), \"" + prefix + "_info\");\n    var values = new " + c.Managed + "[count];\n    fixed (" + c.Managed + "* data = values) NativeError.ThrowIfFailed(Copy" + c.Name + "(token, data, count), \"" + prefix + "_copy\");\n    return new(values" + (c.Sequence ? "" : ", lower") + ");\n  }");
            kind++;
        }
        h.AppendLine("#ifdef __cplusplus\n}\n#endif"); cs.AppendLine("}");
        return [
            new("src/OcctSharp.Native/generated/Foundation/" + stem + ".h", h.ToString(), OcctProductModule.Foundation, GeneratedApiLayer.Raw, "CopiedCollections"),
            new("src/OcctSharp.Native/generated/Foundation/" + stem + ".cpp", cpp.ToString(), OcctProductModule.Foundation, GeneratedApiLayer.Raw, "CopiedCollections"),
            new("src/OcctSharp.Native/generated/Foundation/OcctSharp.Foundation.CopiedSupport.Generated.hxx", Template("copied-collections-native.txt"), OcctProductModule.Foundation, GeneratedApiLayer.Raw, "CopiedCollections"),
            new("src/OcctSharp/Generated/Foundation/Foundation.CopiedCollections.Generated.cs", cs.ToString(), OcctProductModule.Foundation, GeneratedApiLayer.SafeManaged, "CopiedCollections"),
        ];
    }
}
